JavaScript基本数据类型和引用数据类型的深入理解
📚
两种类型的根本区别
1. 存储位置
// 基本类型：存储在栈内存中let a = 10;let b = &quot;hello&quot;;// 引用类型：存储在堆内存中，栈内存存储的是引用地址let obj1 = &#123; name: &quot;张三&quot; &#125;;let arr1 = [1, 2, 3];
2. 赋值操作的区别
// 基本类型：赋值会创建新的副本let a = 10;let b = a;  // b获得了一个新的值10a = 20;     // 修改a不会影响bconsole.log(b);  // 输出：10// 引用类型：赋值会共享引用let obj1 = &#123; name: &quot;张三&quot; &#125;;let obj2 = obj1;  // obj2获得了对同一对象的引用obj1.name = &quot;李四&quot;;  // 通过obj1修改对象console.log(obj2.name);  // 输出：&quot;李四&quot;（obj2也受影响）
3. 比较操作的区别
// 基本类型：比较值let a = 10;let b = 10;console.log(a === b);  // true（值相同）// 引用类型：比较引用地址let obj1 = &#123; name: &quot;张三&quot; &#125;;let obj2 = &#123; name: &quot;张三&quot; &#125;;console.log(obj1 === obj2);  // false（不同对象）
4. 参数传递
// 基本类型：传递值function changeValue(x) &#123;    x = 20;    console.log(&quot;函数内部：&quot;, x);  // 20&#125;let num = 10;changeValue(num);console.log(&quot;函数外部：&quot;, num);  // 10（不受影响）// 引用类型：传递引用function changeObject(obj) &#123;    obj.name = &quot;李四&quot;;    console.log(&quot;函数内部：&quot;, obj.name);  // &quot;李四&quot;&#125;let person = &#123; name: &quot;张三&quot; &#125;;changeObject(person);console.log(&quot;函数外部：&quot;, person.name);  // &quot;李四&quot;（被修改）
三、常见问题和解决方案
1. 引用类型的拷贝
// 1. 浅拷贝// 方法一：Object.assign()let original = &#123; name: &quot;张三&quot;, info: &#123; age: 20 &#125; &#125;;let shallowCopy1 = Object.assign(&#123;&#125;, original);// 方法二：展开运算符let shallowCopy2 = &#123; ...original &#125;;// 2. 深拷贝// 方法一：JSON转换（有局限性）let deepCopy1 = JSON.parse(JSON.stringify(original));// 方法二：递归实现function deepClone(obj) &#123;    if (obj === null || typeof obj !== &#x27;object&#x27;) return obj;    let copy = Array.isArray(obj) ? [] : &#123;&#125;;    for (let key in obj) &#123;        if (obj.hasOwnProperty(key)) &#123;            copy[key] = deepClone(obj[key]);        &#125;    &#125;    return copy;&#125;
JavaScript函数学习笔记 📚
一、函数基础
1. 函数的定义方式
// 1. 函数声明function sayHello(name) &#123;    return &quot;Hello, &quot; + name;&#125;// 2. 函数表达式const sayHello = function(name) &#123;    return &quot;Hello, &quot; + name;&#125;;// 3. 箭头函数（ES6）const sayHello = (name) =&gt; &#123;    return &quot;Hello, &quot; + name;&#125;;// 简写形式const sayHello = name =&gt; &quot;Hello, &quot; + name;// 4. 构造函数（不推荐）const sayHello = new Function(&quot;name&quot;, &quot;return &#x27;Hello, &#x27; + name&quot;);
2. 构造函数
构造函数是用来创建和初始化对象的特殊函数。作为创建具有相同属性和方法的多个对象的模板。
// 基本构造函数function Person(name, age)&#123;    this.name=name;    this.age=age;    this.sayHello=()=&gt;&#123;        console.log(`你好，我是$&#123;this.name&#125;`);    &#125;&#125;// 创建实例new Person(&#x27;张三&#x27;, 18).sayHello();//你好，我是张三
3. new操作符的执行过程
function Person(name) &#123;    this.name = name;&#125;// new操作符的执行过程等同于：function createPerson(name) &#123;    // 1. 创建新对象    const obj = &#123;&#125;;        // 2. 设置原型链    Object.setPrototypeOf(obj, Person.prototype);        // 3. 绑定this并执行构造函数    const result = Person.call(obj, name);        // 4. 返回新对象    return typeof result === &#x27;object&#x27; ? result : obj;&#125;
二、构造函数的进阶用法
1. 原型方法
// 1. 在原型上添加方法（推荐）function Person(name, age) &#123;    this.name = name;    this.age = age;&#125;// 添加到原型上的方法会被所有实例共享Person.prototype.sayHello = function() &#123;    console.log(`你好，我是$&#123;this.name&#125;`);&#125;;// 2. 原型方法vs实例方法function Animal(name) &#123;    this.name = name;    // 实例方法：每个实例都会创建一个新的函数副本    this.sayName = function() &#123;        console.log(this.name);    &#125;;&#125;// 原型方法：所有实例共享同一个函数Animal.prototype.sayHello = function() &#123;    console.log(`Hello, $&#123;this.name&#125;`);&#125;;
2. 私有属性和方法
// 1. 使用闭包实现私有属性function Counter() &#123;    // 私有变量    let count = 0;        // 特权方法（可以访问私有变量）    this.increment = function() &#123;        return ++count;    &#125;;        this.getCount = function() &#123;        return count;    &#125;;&#125;// 2. 使用Symbol实现私有属性（ES6+）const privateProperty = Symbol(&#x27;private&#x27;);function MyClass() &#123;    this[privateProperty] = &quot;这是私有的&quot;;&#125;
3. 构造函数的继承
// 1. 原型链继承function Animal(name) &#123;    this.name = name;&#125;Animal.prototype.sayName = function() &#123;    console.log(this.name);&#125;;function Dog(name, breed) &#123;    // 调用父类构造函数    Animal.call(this, name);    this.breed = breed;&#125;// 设置原型链Dog.prototype = Object.create(Animal.prototype);Dog.prototype.constructor = Dog;// 2. class语法继承（现代方式）class Animal &#123;    constructor(name) &#123;        this.name = name;    &#125;    sayName() &#123;        console.log(this.name);    &#125;&#125;class Dog extends Animal &#123;    constructor(name, breed) &#123;        super(name);        this.breed = breed;    &#125;&#125;
三、构造函数的最佳实践
1. 安全的构造函数
function Person(name) &#123;    // 确保使用new调用    if (!(this instanceof Person)) &#123;        return new Person(name);    &#125;    this.name = name;&#125;// 或使用new.targetfunction SafePerson(name) &#123;    if (!new.target) &#123;        return new SafePerson(name);    &#125;    this.name = name;&#125;
4. 立即执行函数表达式（IIFE）
// 1. 基本语法(function() &#123;    console.log(&quot;我会立即执行&quot;);&#125;)();// 2. 带参数的IIFE(function(a, b) &#123;    console.log(a + b);  // 输出：3&#125;)(1, 2);// 3. 返回值的IIFEconst result = (function(a, b) &#123;    return a + b;&#125;)(1, 2);console.log(result);  // 输出：3// 4. 箭头函数形式的IIFE(() =&gt; &#123;    console.log(&quot;箭头函数IIFE&quot;);&#125;)();// 5. 带命名的IIFE（便于调试）(function calculateSum(a, b) &#123;    console.log(a + b);&#125;)(1, 2);
二、函数的高级特性
1. 作用域和闭包
// 1. 词法作用域let globalVar = &quot;全局变量&quot;;function outer() &#123;    let outerVar = &quot;外部变量&quot;;        function inner() &#123;        let innerVar = &quot;内部变量&quot;;        console.log(globalVar, outerVar, innerVar);    &#125;        return inner;&#125;// 2. 闭包示例function counter() &#123;    let count = 0;    return &#123;        increment() &#123; return ++count; &#125;,        decrement() &#123; return --count; &#125;,        getCount() &#123; return count; &#125;    &#125;;&#125;const myCounter = counter();console.log(myCounter.increment()); // 1console.log(myCounter.increment()); // 2
2. this关键字
// 1. 全局上下文console.log(this === window); // 浏览器环境中为true// 2. 对象方法中的thisconst user = &#123;    name: &quot;张三&quot;,    sayHi() &#123;        console.log(`Hi, $&#123;this.name&#125;!`);    &#125;&#125;;// 3. 构造函数中的thisfunction User(name) &#123;    this.name = name;    this.sayHi = function() &#123;        console.log(`Hi, $&#123;this.name&#125;!`);    &#125;;&#125;// 4. 箭头函数中的thisconst obj = &#123;    name: &quot;张三&quot;,    sayHiLater() &#123;        setTimeout(() =&gt; &#123;            console.log(`Hi, $&#123;this.name&#125;!`);        &#125;, 1000);    &#125;&#125;;
3. 函数绑定
// 1. bind方法const user = &#123;    name: &quot;张三&quot;,    sayHi() &#123;        console.log(`Hi, $&#123;this.name&#125;!`);    &#125;&#125;;const sayHi = user.sayHi.bind(user);// 2. call方法function greet(greeting) &#123;    console.log(`$&#123;greeting&#125;, $&#123;this.name&#125;!`);&#125;greet.call(user, &quot;Hello&quot;);// 3. apply方法greet.apply(user, [&quot;Hello&quot;]);
4.arguments
在调用函数时，浏览器每次都会传递两个隐含的参数：

函数的上下文对象this
封装实参的对象的arguments

function fun()&#123;    // 在调用函数时，会自动传入一个arguments对象，该对象包含了传递的实参。    // arguments对象是一个类数组对象，具有length属性和索引属性，可以遍历。    console.log(arguments.length); //2    console.log(arguments[1]); //true    console.log(arguments.callee === fun); // true callee属性是正在执行的函数的对象&#125;fun(&quot;hello&quot;,true);
三、函数的应用模式
1. 回调函数
// 1. 简单回调function fetchData(callback) &#123;    setTimeout(() =&gt; &#123;        const data = &#123; id: 1, name: &quot;张三&quot; &#125;;        callback(data);    &#125;, 1000);&#125;// 2. 错误优先回调function readFile(path, callback) &#123;    fs.readFile(path, (error, data) =&gt; &#123;        if (error) &#123;            callback(error);            return;        &#125;        callback(null, data);    &#125;);&#125;
2. Promise和async/await
// 1. Promisefunction fetchUserData(id) &#123;    return new Promise((resolve, reject) =&gt; &#123;        setTimeout(() =&gt; &#123;            const user = &#123; id, name: &quot;张三&quot; &#125;;            resolve(user);        &#125;, 1000);    &#125;);&#125;// 2. async/awaitasync function getUser(id) &#123;    try &#123;        const user = await fetchUserData(id);        return user;    &#125; catch (error) &#123;        console.error(&quot;获取用户失败:&quot;, error);    &#125;&#125;
3. 函数式编程
// 1. 纯函数function add(a, b) &#123;    return a + b;&#125;// 2. 高阶函数function multiply(factor) &#123;    return function(number) &#123;        return number * factor;    &#125;;&#125;// 3. 函数组合const compose = (...fns) =&gt; x =&gt; fns.reduceRight((y, f) =&gt; f(y), x);
四、最佳实践
1. 函数设计原则
// 1. 单一职责function validateEmail(email) &#123;    return /\S+@\S+\.\S+/.test(email);&#125;// 2. 纯函数设计function calculateTotal(items) &#123;    return items.reduce((total, item) =&gt; total + item.price, 0);&#125;// 3. 参数验证function createUser(userData) &#123;    if (!userData.name) throw new Error(&quot;用户名是必需的&quot;);    if (!userData.email) throw new Error(&quot;邮箱是必需的&quot;);    // ...&#125;
2. 性能优化
// 1. 函数缓存（记忆化）function memoize(fn) &#123;    const cache = new Map();    return function(...args) &#123;        const key = JSON.stringify(args);        if (cache.has(key)) return cache.get(key);        const result = fn.apply(this, args);        cache.set(key, result);        return result;    &#125;;&#125;// 2. 防抖function debounce(fn, delay) &#123;    let timer = null;    return function(...args) &#123;        clearTimeout(timer);        timer = setTimeout(() =&gt; fn.apply(this, args), delay);    &#125;;&#125;// 3. 节流function throttle(fn, limit) &#123;    let inThrottle;    return function(...args) &#123;        if (!inThrottle) &#123;            fn.apply(this, args);            inThrottle = true;            setTimeout(() =&gt; inThrottle = false, limit);        &#125;    &#125;;&#125;
3. 错误处理
// 1. try-catchfunction divide(a, b) &#123;    try &#123;        if (b === 0) throw new Error(&quot;除数不能为0&quot;);        return a / b;    &#125; catch (error) &#123;        console.error(&quot;计算错误:&quot;, error);        return null;    &#125;&#125;// 2. 自定义错误class ValidationError extends Error &#123;    constructor(message) &#123;        super(message);        this.name = &quot;ValidationError&quot;;    &#125;&#125;
记住： 1. 函数名应该是动词或动词短语 2. 保持函数的纯粹性 3.
适当使用注释说明复杂逻辑 4. 避免副作用 5.
控制函数的参数数量（建议不超过3个）
IIFE的使用场景

避免全局作用域污染 // 不好的做法：污染全局作用域var counter = 0;function increment() &#123;    counter++;&#125;// 好的做法：使用IIFEconst counter = (function() &#123;    let count = 0;  // 私有变量    return &#123;        increment() &#123;            return ++count;        &#125;,        getCount() &#123;            return count;        &#125;    &#125;;&#125;)();console.log(counter.increment());  // 1console.log(counter.getCount());   // 1
创建私有作用域 // 模块模式const myModule = (function() &#123;    // 私有变量和方法    let privateVar = 0;    function privateFunction() &#123;        return privateVar;    &#125;        // 公共API    return &#123;        publicMethod() &#123;            return privateFunction();        &#125;,        publicVar: &quot;我是公共的&quot;    &#125;;&#125;)();
异步操作中保存状态 // 循环中使用IIFEfor (var i = 0; i &lt; 3; i++) &#123;    (function(index) &#123;        setTimeout(() =&gt; &#123;            console.log(index);        &#125;, 1000);    &#125;)(i);&#125;

IIFE的特点

语法特征：

函数表达式被括号包裹
最后有一对执行括号
可以传递参数

优点：

创建独立的作用域
避免命名冲突
保护私有变量
模块化代码

注意事项： // 1. 分号问题// 如果前面的代码没有分号结尾，可能导致错误const a = 1(function() &#123;&#125;)()  // 错误：被解释为函数调用// 正确做法const a = 1;(function() &#123;&#125;)()// 2. 不同的写法// 这些都是有效的IIFE写法(function() &#123;&#125;)();  // 推荐(function() &#123;&#125;());!function() &#123;&#125;();+function() &#123;&#125;();

现代替代方案

使用块级作用域 // ES6之前用IIFE(function() &#123;    var temp = &quot;我是临时变量&quot;;    // ...&#125;)();// ES6可以使用块级作用域&#123;    let temp = &quot;我是临时变量&quot;;    // ...&#125;
使用模块 // module.jsexport const counter = &#123;    count: 0,    increment() &#123;        return ++this.count;    &#125;&#125;;// main.jsimport &#123; counter &#125; from &#x27;./module.js&#x27;;

最佳实践： 1. 在需要独立作用域时使用IIFE 2.
现代JavaScript优先使用模块和块级作用域 3.
IIFE适合用于旧代码兼容和特定场景 4. 注意代码可读性，适当添加注释
五、声明提前（Hoisting）
1. 基本概念
声明提前是JavaScript中的一个机制，它会将变量和函数的声明移动到其所在作用域的顶部。
// 1. 变量声明提前console.log(a);     // undefined（不会报错）var a = 1;// 上面的代码等同于：var a;             // 声明被提前console.log(a);    // undefineda = 1;            // 赋值保持在原位置// 2. let和const不会声明提前console.log(b);     // ReferenceError: Cannot access &#x27;b&#x27; before initializationlet b = 2;// 3. 函数声明提前sayHello();        // &quot;Hello!&quot;（可以正常运行）function sayHello() &#123;    console.log(&quot;Hello!&quot;);&#125;// 4. 函数表达式不会提前fn2();              // TypeError: fn2 is not a functionvar fn2 = function() &#123;    console.log(&quot;函数2&quot;);&#125;;
3. 声明提前的作用域
// 1. 全局作用域var global = &quot;全局变量&quot;;function test() &#123;    console.log(global);  // undefined（不是&quot;全局变量&quot;）    var global = &quot;局部变量&quot;;    console.log(global);  // &quot;局部变量&quot;&#125;// 2. 函数作用域function outer() &#123;    console.log(inner);   // undefined    var inner = &quot;内部变量&quot;;        function innerFn() &#123;        console.log(inner);  // &quot;内部变量&quot;    &#125;    innerFn();&#125;
4. 常见陷阱和最佳实践

函数声明覆盖 // 可能导致问题的代码function myFunction() &#123;    console.log(&quot;版本1&quot;);&#125;myFunction();  // &quot;版本2&quot;function myFunction() &#123;    console.log(&quot;版本2&quot;);&#125;

5. 函数和变量的创建顺序
在JavaScript中，声明提前遵循以下优先级规则：
// 1. 函数声明优先于变量声明console.log(foo);  // [Function: foo]var foo = &quot;变量foo&quot;;function foo() &#123;    return &quot;函数foo&quot;;&#125;// 上述代码在执行时的实际顺序：function foo() &#123;   // 1. 首先处理函数声明    return &quot;函数foo&quot;;&#125;var foo;           // 2. 变量声明被忽略（因为已经存在同名函数）console.log(foo);  // 3. 输出函数定义foo = &quot;变量foo&quot;;   // 4. 变量赋值// 2. 同名函数声明会相互覆盖function bar() &#123;    return &quot;第一个函数&quot;;&#125;function bar() &#123;    return &quot;第二个函数&quot;;&#125;console.log(bar());  // &quot;第二个函数&quot;
六、apply 和 call 方法
用途
apply 和 call
都是函数对象的方法，用于改变函数执行时的上下文（即改变函数内部的
this 指向）。
语法
func.call(thisArg, param1, param2, ...)func.apply(thisArg, [param1, param2, ...])
区别

call 方法：参数需要一个一个传递
apply 方法：参数以数组形式传递

示例
1. 基本使用
const person = &#123;    name: &#x27;张三&#x27;,    sayHi: function(greeting) &#123;        console.log(`$&#123;greeting&#125;，我是$&#123;this.name&#125;`);    &#125;&#125;;const other = &#123;    name: &#x27;李四&#x27;&#125;;// 使用 callperson.sayHi.call(other, &#x27;你好&#x27;);  // 输出：你好，我是李四// 使用 applyperson.sayHi.apply(other, [&#x27;你好&#x27;]); // 输出：你好，我是李四
2. 实际应用场景
2.1 借用数组方法
// 将类数组转换为真正的数组function convert() &#123;    return Array.prototype.slice.call(arguments);&#125;console.log(convert(1, 2, 3)); // 输出：[1, 2, 3]// 或使用 apply 找出数组最大值const numbers = [5, 6, 2, 3, 7];const max = Math.max.apply(null, numbers);console.log(max); // 输出：7
2.2 继承
function Animal(name) &#123;    this.name = name;&#125;function Cat(name, color) &#123;    // 调用 Animal 构造函数，并将 this 指向 Cat 实例    Animal.call(this, name);    this.color = color;&#125;const cat = new Cat(&#x27;咪咪&#x27;, &#x27;白色&#x27;);console.log(cat.name, cat.color); // 输出：咪咪 白色
关键点

this 绑定

第一个参数决定了函数内部的 this 指向
如果第一个参数为 null 或
undefined，this
会指向全局对象（非严格模式）或保持为
null/undefined（严格模式）

参数传递

call：func.call(thisArg, arg1, arg2, ...)
apply：func.call(thisArg, [arg1, arg2, ...])

使用场景

借用其他对象的方法
继承时调用父类构造函数
调用需要特定 this 值的函数


最佳实践

当参数数量固定时，优先使用 call，代码更直观
当参数数量不固定或参数本身就是数组时，使用 apply
在现代 JavaScript 中，可以考虑使用展开运算符 ... 代替
apply： const numbers = [5, 6, 2, 3, 7];const max = Math.max(...numbers); // 替代 Math.max.apply(null, numbers)

注意事项

在严格模式下，如果第一个参数为 null 或
undefined，this 不会被转换为全局对象
这两个方法都会立即执行函数
如果需要稍后执行，可以考虑使用 bind 方法

JavaScript原型与原型链学习笔记
📚
一、原型基础概念


image-20250312020925534

我们所创建的每一个函数，解析器都会向函数中添加一个属性prototype
这个属性对应着一个对象，这个对象就是我们所谓的原型对象
当函数以构造函数的形式调用时，它所创建的对象中都会有一个隐含的属性，它指向该构造函数的原型对象，我们可以通过__proto__来访问该属性
原型对象就相当于一个公共的区域，所有同一个类的实例都可以访问到这个原型对象，我们可以将对象中共有的内容，统一设置到原型对象中。
当我们访问对象的一个属性或方法时，它会先在对象自身中寻找，如果有则直接使用，如果没有则会去原型对象中寻找，如果找到则直接使用
1. 函数的prototype属性
// 每个函数都有prototype属性function Person(name) &#123;    this.name = name;&#125;console.log(Person.prototype); // &#123;constructor: ƒ&#125;// 向原型中添加方法Person.prototype.sayHello = function() &#123;    console.log(`Hello, $&#123;this.name&#125;`);&#125;;
2. 对象的__proto__属性
// 创建实例const person1 = new Person(&quot;张三&quot;);const person2 = new Person(&quot;李四&quot;);// 实例通过__proto__访问原型对象console.log(person1.__proto__ === Person.prototype); // trueconsole.log(person2.__proto__ === Person.prototype); // true// 使用Object.getPrototypeOf()console.log(Object.getPrototypeOf(person1) === Person.prototype); // true
3. 原型链查找机制
function Person(name) &#123;    this.name = name;&#125;Person.prototype.sayHello = function() &#123;    console.log(`Hello, $&#123;this.name&#125;`);&#125;;const person = new Person(&quot;张三&quot;);// 用 in 检查对象或原型对象中有无某个属性console.log(&quot;sayHello&quot; in Person.prototype); //true// 用 hasOwnProperty 检查对象自身有无某个属性console.log(User.hasOwnProperty(&quot;sayHello&quot;)); // false// 查找顺序：// 1. 先在实例对象中查找person.name;  // 在实例中找到 &quot;张三&quot;// 2. 如果实例中没有，则在原型对象中查找person.sayHello();  // 在原型中找到方法// 3. 如果原型中没有，则继续在原型的原型中查找，直到找到Object对象的原型。Object对象的原型没有原型，是nullconsole.log(Person.__proto__.__proto__.hasOwnProperty(&quot;hasOwnProperty&quot;));// true Person的原型对象的原型对象中有hasOwnProperty属性console.log(Person.__proto__.__proto__.hasOwnProperty(&quot;toString&quot;));// true Person的原型对象的原型对象中有toString属性//Object对象的原型没有原型，是nullconsole.log(Object.__proto__.__proto__);// null prototypeperson.toString();  // 在Object.prototype中找到方法// 4. 如果最终在Object中也没找到，则返回undefinedperson.notExist;  // undefined
二、原型的实际应用
1. 共享方法和属性
// 不推荐：每个实例都创建一个新方法function Dog(name) &#123;    this.name = name;    this.bark = function() &#123;  // 每个实例都有一个bark方法副本        console.log(&quot;汪汪!&quot;);    &#125;;&#125;// 推荐：将方法放在原型上共享function Dog(name) &#123;    this.name = name;&#125;Dog.prototype.bark = function() &#123;  // 所有实例共享同一个方法    console.log(&quot;汪汪!&quot;);&#125;;
2. 原型继承
// 父类function Animal(name) &#123;    this.name = name;&#125;Animal.prototype.eat = function() &#123;    console.log(`$&#123;this.name&#125;正在吃东西`);&#125;;// 子类function Dog(name) &#123;    Animal.call(this, name);  // 继承属性&#125;// 继承方法（设置原型链）Dog.prototype = Object.create(Animal.prototype);Dog.prototype.constructor = Dog;  // 修复constructor指向// 添加子类自己的方法Dog.prototype.bark = function() &#123;    console.log(&quot;汪汪!&quot;);&#125;;
3. 原型链检测
// 1. instanceof 运算符const dog = new Dog(&quot;小黑&quot;);console.log(dog instanceof Dog);     // trueconsole.log(dog instanceof Animal);  // trueconsole.log(dog instanceof Object);  // true// 2. isPrototypeOf() 方法console.log(Dog.prototype.isPrototypeOf(dog));    // trueconsole.log(Animal.prototype.isPrototypeOf(dog)); // true// 3. getPrototypeOf() 方法console.log(Object.getPrototypeOf(dog) === Dog.prototype); // true
三、注意事项和最佳实践
1. 属性遮蔽（Property
Shadowing）
function Person() &#123;&#125;Person.prototype.name = &quot;原型上的名字&quot;;const person = new Person();console.log(person.name);  // &quot;原型上的名字&quot;person.name = &quot;实例上的名字&quot;;  // 创建自己的属性console.log(person.name);  // &quot;实例上的名字&quot;delete person.name;  // 删除实例上的属性console.log(person.name);  // &quot;原型上的名字&quot;
2. 原型的动态性
function Person() &#123;&#125;const person = new Person();// 在创建实例后修改原型Person.prototype.sayHello = function() &#123;    console.log(&quot;Hello!&quot;);&#125;;person.sayHello();  // &quot;Hello!&quot; - 可以访问新添加的方法// 但是完全替换原型会断开连接Person.prototype = &#123;    sayHi: function() &#123;        console.log(&quot;Hi!&quot;);    &#125;&#125;;person.sayHi();  // TypeError: person.sayHi is not a function
3. 最佳实践
// 1. 使用Object.create()创建干净的原型链const parent = &#123;    sayHello() &#123;        console.log(&quot;Hello!&quot;);    &#125;&#125;;const child = Object.create(parent);// 2. 使用class语法（推荐）class Animal &#123;    constructor(name) &#123;        this.name = name;    &#125;        eat() &#123;        console.log(`$&#123;this.name&#125;正在吃东西`);    &#125;&#125;class Dog extends Animal &#123;    bark() &#123;        console.log(&quot;汪汪!&quot;);    &#125;&#125;
JavaScript垃圾回收机制详解📚
一、基本概念
1. 什么是垃圾回收
JavaScript会自动进行内存管理和垃圾回收（Garbage
Collection，简称GC），主要目的是： - 识别不再使用的内存（垃圾） -
回收这些内存供后续使用 - 防止内存泄漏
二、主要算法
1.
标记-清除算法（Mark-and-Sweep）
// 标记-清除算法的工作示例let user = &#123;    name: &quot;John&quot;&#125;;user = null;  // 对象变成垃圾，将在下次GC时被回收
工作步骤： 1. 垃圾回收器找到所有根对象（全局对象） 2.
标记从根对象可达的所有对象 3. 清除未被标记的对象
2. 引用计数算法（Reference
Counting）
// 引用计数示例let obj = &#123;     // 引用计数 = 1    name: &quot;测试&quot;&#125;;let reference = obj;  // 引用计数 = 2obj = null;          // 引用计数 = 1reference = null;    // 引用计数 = 0，可以被回收
3. 循环引用问题
function createCycle() &#123;    let obj1 = &#123;&#125;;    let obj2 = &#123;&#125;;        obj1.ref = obj2;    // obj1 引用 obj2    obj2.ref = obj1;    // obj2 引用 obj1        return &quot;cycle created&quot;;&#125;createCycle();  // 函数执行完后，obj1和obj2互相引用，但都不可访问
三、内存泄漏的常见情况
1. 意外的全局变量
// 错误示例function leak() &#123;    leakedVariable = &quot;我会泄漏到全局&quot;;  // 没有使用var/let/const&#125;// 正确做法&#x27;use strict&#x27;;  // 使用严格模式function noLeak() &#123;    let safeVariable = &quot;我是安全的局部变量&quot;;&#125;
2. 被遗忘的定时器
// 内存泄漏示例function setLeakyTimer() &#123;    const someData = &#123; /* 大量数据 */ &#125;;    setInterval(() =&gt; &#123;        console.log(someData);    &#125;, 1000);&#125;// 正确做法function setProperTimer() &#123;    const timerId = setInterval(() =&gt; &#123;        console.log(&#x27;tick&#x27;);    &#125;, 1000);        // 在适当的时候清除定时器    clearInterval(timerId);&#125;
3. 闭包导致的泄漏
// 潜在的内存泄漏function createLeak() &#123;    const largeData = new Array(1000000);        return function() &#123;        console.log(largeData[0]);  // 持有对largeData的引用    &#125;&#125;// 更好的做法function createNonLeak() &#123;    const largeData = new Array(1000000);    const firstItem = largeData[0];  // 只保留需要的数据        return function() &#123;        console.log(firstItem);    &#125;&#125;
4. DOM引用
// 可能导致内存泄漏的DOM引用let elements = &#123;    button: document.getElementById(&#x27;button&#x27;),    image: document.getElementById(&#x27;image&#x27;),    text: document.getElementById(&#x27;text&#x27;)&#125;;// 解除引用function removeButton() &#123;    document.body.removeChild(document.getElementById(&#x27;button&#x27;));    // 应该同时解除引用    elements.button = null;&#125;
四、最佳实践
1. 避免内存泄漏
// 1. 及时清除定时器const timer = setTimeout(() =&gt; &#123;    // 操作&#125;, 1000);clearTimeout(timer);// 2. 及时解除事件监听function addListener() &#123;    const element = document.getElementById(&#x27;myButton&#x27;);    const handler = () =&gt; &#123;        console.log(&#x27;clicked&#x27;);    &#125;;    element.addEventListener(&#x27;click&#x27;, handler);        // 清理函数    return () =&gt; &#123;        element.removeEventListener(&#x27;click&#x27;, handler);    &#125;;&#125;// 3. 使用WeakMap/WeakSetconst cache = new WeakMap();let object = &#123; data: &#x27;cached&#x27; &#125;;cache.set(object, &#x27;metadata&#x27;);object = null;  // 对象可被回收
2. 性能优化建议
// 1. 对象池模式const objectPool = &#123;    _pool: [],        acquire() &#123;        return this._pool.pop() || &#123;&#125;;    &#125;,        release(obj) &#123;        Object.keys(obj).forEach(key =&gt; &#123;            delete obj[key];        &#125;);        this._pool.push(obj);    &#125;&#125;;// 2. 及时释放大型数据function processData(data) &#123;    // 处理数据    const result = transform(data);        // 清除原始数据引用    data = null;        return result;&#125;
3. 监控内存使用
// 在浏览器中监控内存使用console.log(performance.memory);// Node.js中监控内存使用const used = process.memoryUsage();console.log(&#123;    heapTotal: `$&#123;Math.round(used.heapTotal / 1024 / 1024 * 100) / 100&#125; MB`,    heapUsed: `$&#123;Math.round(used.heapUsed / 1024 / 1024 * 100) / 100&#125; MB`&#125;);
JavaScript数组对象方法笔记
// 创建数组,数组也是内建对象let fruits = [&quot;苹果&quot;, &quot;香蕉&quot;, &quot;橙子&quot;];let numbers = [1, 2, 3, 4, 5];let names = new Array(1,2,3);names[names.length]=1;// 使用数组console.log(fruits[0]);              // 输出：苹果fruits.push(&quot;梨&quot;,&quot;西瓜&quot;);                   // 从末尾添加新元素fruits.pop();// 删除数组最后一个元素并返回fruits.unshift(&quot;奥特曼&quot;);  //从最开始添加元素fruits.shift();// 删除数组第一个元素并返回// slice 不会影响原数组。用于从数组中提取出一部分元素，并返回一个新数组。// 左闭右开区间const array = [1, 2, 3, 4, 5];console.log(array.slice(1, 3)); // 输出 [2, 3]// 负索引console.log(array.slice(-3, -1)); // 输出 [3, 4]const array = [1, 2, 3, 4, 5];// splice 会影响原数组,param1 为开始位置,param2 为删除的个数，param3及以后的元素将会从开始删除索引位置替换进去console.log(array.splice(1, 2,&quot;张三&quot;,&quot;李四&quot;)); // [2, 3]console.log(array);//[ 1,&quot;张三&quot;,&quot;李四&quot;, 4, 5 ]// concat 不会影响原数组。将多个数组合并成一个数组let array = [1, 2, 3];let array2 = [4,5,6];console.log(array.concat(array2,&quot;不高兴&quot;,&quot;没头脑&quot;)); //[ 1, 2, 3, 4, 5, 6, &#x27;不高兴&#x27;, &#x27;没头脑&#x27; ]// join 不会影响原数组。将数组元素用连接符连接起来。let array = [&quot;没头脑&quot;,&quot;不高兴&quot;];console.log(array.join(&quot;@&quot;)); // 没头脑@不高兴// reverse 颠倒原数组let array = [&quot;没头脑&quot;,&quot;不高兴&quot;];console.log(array.reverse()); // [ &#x27;不高兴&#x27;, &#x27;没头脑&#x27; ]

使用 for...of 遍历可迭代对象。
使用 forEach 进行副作用操作。
使用 map 进行数组元素的转换。
使用 filter 进行数组元素的筛选。
使用 reduce 进行数组的聚合操作。

1. for…of
用途
for...of
循环用于遍历可迭代对象（如数组、字符串、Map、Set等）。
使用方法
for (const element of iterable) &#123;    // 处理每个元素&#125;
参数说明

iterable: 任何可迭代对象。

返回值

无返回值。

示例
const array = [1, 2, 3];for (const num of array) &#123;    console.log(num); // 输出 1, 2, 3&#125;

2. forEach
用途
forEach 方法用于对数组的每个元素执行一次提供的函数。
使用方法
array.forEach((element, index, array) =&gt; &#123;    // 处理每个元素&#125;);
参数说明

element: 当前处理的数组元素。
index: 当前元素的索引（可选）。
array: 调用 forEach 的数组（可选）。

返回值

无返回值。

示例
const array = [1, 2, 3];array.forEach((num) =&gt; &#123;    console.log(num); // 输出 1, 2, 3&#125;);

3. map
用途
map
方法创建一个新数组，结果是对原数组中的每个元素调用一个提供的函数后的返回值。
使用方法
const newArray = array.map((element, index, array) =&gt; &#123;    // 返回处理后的元素&#125;);
参数说明

element: 当前处理的数组元素。
index: 当前元素的索引（可选）。
array: 调用 map 的数组（可选）。

返回值

返回一个新数组。

示例
const array = [1, 2, 3];const doubled = array.map(num =&gt; num * 2);console.log(doubled); // 输出 [2, 4, 6]

4. filter
用途
filter 方法创建一个新数组，包含所有通过测试的元素。
使用方法
const newArray = array.filter((element, index, array) =&gt; &#123;    // 返回 true 或 false&#125;);
参数说明

element: 当前处理的数组元素。
index: 当前元素的索引（可选）。
array: 调用 filter 的数组（可选）。

返回值

返回一个新数组，包含所有通过测试的元素。

示例
const array = [1, 2, 3, 4];const evens = array.filter(num =&gt; num % 2 === 0);console.log(evens); // 输出 [2, 4]

5. reduce
用途
reduce 方法对数组中的每个元素执行一个 reducer
函数，最终计算出一个单一的值。
使用方法
const result = array.reduce((accumulator, currentValue, index, array) =&gt; &#123;    // 返回更新后的累加器&#125;, initialValue);
参数说明

accumulator: 累加器，累计回调的返回值。
currentValue: 当前处理的数组元素。
index: 当前元素的索引（可选）。
array: 调用 reduce 的数组（可选）。
initialValue:
作为第一次调用回调时第一个参数的值（可选）。

返回值

返回最终的累加值。

示例
const array = [1, 2, 3, 4];const sum = array.reduce((acc, num) =&gt; acc + num, 0);console.log(sum); // 输出 10
6. 数组去重实现

对于简单数组去重，优先使用 Set 方法
需要保持数组原有顺序时，可以使用 filter 方法
需要在遍历过程中进行复杂操作时，可以使用 splice 方法

方法一：使用双重循环和splice
这种方法通过比较每个元素与其后的所有元素，发现重复就删除。
let array = [1, 2, 2, 3, 4, 5];for (let i = 0; i &lt; array.length; i++) &#123;    // 遍历该元素后的所有元素依次比较    for (let j = i + 1; j &lt; array.length; j++) &#123;        if (array[i] === array[j]) &#123;            array.splice(j, 1); // 删除重复元素            // 因为数组长度减少了1，所以索引也要减1。即删除了当前元素，后一个元素顶上来了,此时比较下一个元素将会漏一个元素没比较            j--;         &#125;    &#125;&#125;console.log(array); // 输出 [1, 2, 3, 4, 5]
方法二：使用Set（推荐）
let array = [1, 2, 2, 3, 4, 5];array = [...new Set(array)];console.log(array); // 输出 [1, 2, 3, 4, 5]
方法三：使用filter和indexOf
let array = [1, 2, 2, 3, 4, 5];// 元素在数组中首次出现的位置等于其当前索引array = array.filter((item, index) =&gt; array.indexOf(item) === index);console.log(array); // 输出 [1, 2, 3, 4, 5]
