1. 通过ID查询元素
// 获取ID为&quot;myElement&quot;的元素const element = document.getElementById(&#x27;myElement&#x27;);
2. 通过类名查询元素
// 获取所有class为&quot;myClass&quot;的元素（返回HTMLCollection）const elements = document.getElementsByClassName(&#x27;myClass&#x27;);// 遍历所有找到的元素for (let i = 0; i &lt; elements.length; i++) &#123;    console.log(elements[i]);&#125;
3. 通过标签名查询元素
// 获取所有&lt;p&gt;元素（返回HTMLCollection）const paragraphs = document.getElementsByTagName(&#x27;p&#x27;);
4.
使用CSS选择器查询元素（现代方法）
// 获取第一个匹配的元素const element = document.querySelector(&#x27;.myClass&#x27;);// 获取所有匹配的元素（返回NodeList）const elements = document.querySelectorAll(&#x27;div.important&#x27;);// 使用复杂的CSS选择器const nestedElements = document.querySelectorAll(&#x27;#container &gt; .item&#x27;);
获取元素节点的子节点


image-20250318004002936


childNodes属性会获取包括文本节点在内的所有节点，包括空白文本节点
children属性可以获取当前元素的所有子元素
firstChild可以获取当前元素的第一个子节点，包括空白文本节点
firstElementChild可以获取当前元素的第一个子元素

NodeList与HTMLCollection的区别

HTMLCollection：是动态集合，会随DOM的变化而自动更新
NodeList：通常是静态集合，不会自动更新（除了某些特定情况）

这就像是： - HTMLCollection是实时监控的摄像头画面 -
NodeList是拍下的一张照片，不会随场景变化而变化
遍历DOM元素
// 遍历NodeListconst items = document.querySelectorAll(&#x27;.item&#x27;);items.forEach(item =&gt; &#123;    console.log(item.textContent);&#125;);// 遍历HTMLCollection（不支持forEach，需要转换或使用for循环）const divs = document.getElementsByTagName(&#x27;div&#x27;);Array.from(divs).forEach(div =&gt; &#123;    console.log(div.id);&#125;);// 或者使用for循环for (let i = 0; i &lt; divs.length; i++) &#123;    console.log(divs[i].id);&#125;
DOM元素关系导航
DOM树中的元素之间存在父子、兄弟关系，可以通过这些关系导航：
const parent = document.getElementById(&#x27;parent&#x27;);// 获取子元素const children = parent.children;  // 所有子元素const firstChild = parent.firstElementChild;  // 第一个子元素const lastChild = parent.lastElementChild;  // 最后一个子元素// 获取父元素const child = document.getElementById(&#x27;child&#x27;);const parentElement = child.parentElement;// 获取兄弟元素const prevSibling = child.previousElementSibling;  // 前一个兄弟元素const nextSibling = child.nextElementSibling;  // 后一个兄弟元素
实际应用示例
示例1：切换元素的可见性
// HTML: &lt;button id=&quot;toggleBtn&quot;&gt;显示/隐藏&lt;/button&gt;//       &lt;div id=&quot;content&quot;&gt;这是可以切换显示的内容&lt;/div&gt;const toggleBtn = document.getElementById(&#x27;toggleBtn&#x27;);const content = document.getElementById(&#x27;content&#x27;);toggleBtn.addEventListener(&#x27;click&#x27;, function() &#123;    if (content.style.display === &#x27;none&#x27;) &#123;        content.style.display = &#x27;block&#x27;;    &#125; else &#123;        content.style.display = &#x27;none&#x27;;    &#125;&#125;);

