&lt;?xml version=&quot;1.0&quot; encoding=&quot;UTF-8&quot;?&gt;&lt;!-- MyBatis配置文件约束声明 --&gt;&lt;!DOCTYPE mapper        PUBLIC &quot;-//mybatis.org//DTD Mapper 3.0//EN&quot;        &quot;http://mybatis.org/dtd/mybatis-3-mapper.dtd&quot;&gt;&lt;!-- 映射器定义：将XML映射到EmpMapper接口，实现接口方法与SQL的绑定 --&gt;&lt;mapper namespace=&quot;com.luotao.mapper.EmpMapper&quot;&gt;    &lt;!--将重复的sql定义为独立的SQL 片段，&lt;include&gt; 标签用于引用已定义的 SQL 片段，通过 refid 属性指定要引用的片段的 id。--&gt;    &lt;sql id=&quot;allColumns&quot;&gt;        emp_id as &#x27;empId&#x27;,   &lt;!-- 将数据库字段 emp_id 映射为 Employ 对象的属性 empId --&gt;        emp_name as &#x27;empName&#x27;,        emp_salary as &#x27;empSalary&#x27;    &lt;/sql&gt;    &lt;!-- 查询符合条件的所有员工信息         id: 对应Mapper接口方法名         resultType: 返回结果映射的实体类         MyBatis 会根据方法签名自动推断参数类型,可以省略parameterType         在 XML 配置中，resultType 必须显式声明--&gt;    &lt;select id=&quot;list&quot; resultType=&quot;我是在mybatis配置文件中定义的Employ的别名&quot;&gt;        &lt;!-- SQL查询字段与实体类属性映射             通过as别名实现数据库字段到Java属性的映射,解决字段名与属性名不一致的问题             别名与Employ属性名的匹配是大小写不敏感的。例如，empsalary 可以匹配 empSalary。             如果未指定别名，字段名与属性名需要完全一致（包括大小写）。--&gt;        select            &lt;include refid=&quot;allColumns&quot;&gt;&lt;/include&gt;, emp_salary * 2 as &#x27;doubleEmpSalary&#x27;        from t_emp        where        1=1        &lt;if test=&quot;empName != null and empName != &#x27;&#x27; &quot;&gt;            AND (            emp_name LIKE CONCAT(&#x27;%&#x27;, #&#123;empName&#125;, &#x27;%&#x27;)            )        &lt;/if&gt;        &lt;if test=&quot;minEmpSalary != null &quot;&gt;            AND (            emp_salary &gt;= #&#123;minEmpSalary&#125;            )        &lt;/if&gt;    &lt;/select&gt;    &lt;!--  已经配置了mapUnderscoreToCamelCase,这样可以不用编写resultMap,mybatis自动将emp_id映射为实体的empId  --&gt;    &lt;select id=&quot;listByResultMap&quot; resultType=&quot;我是在mybatis配置文件中定义的Employ的别名&quot;&gt;    &lt;!-- &lt;select id=&quot;listByResultMap&quot; resultMap=&quot;employResultMap&quot;&gt; --&gt;        select *, emp_salary * 2 as &#x27;doubleEmpSalary&#x27; from t_emp    &lt;/select&gt;    &lt;!--   描述实体与查询结果的映射规则。这里的命名很规范，可以不使用这个规则，到MyBatis配置文件中配置mapUnderscoreToCamelCase,自动将emp_id映射为实体的empId        &lt;resultMap id=&quot;employResultMap&quot; type=&quot;我是在mybatis配置文件中定义的Employ的别名&quot;&gt;            &lt;id column=&quot;emp_id&quot; property=&quot;empId&quot;/&gt;            &lt;result column=&quot;emp_name&quot; property=&quot;empName&quot;/&gt;            &lt;result column=&quot;emp_salary&quot; property=&quot;empSalary&quot;/&gt;            &lt;result column=&quot;doubleEmpSalary&quot; property=&quot;doubleEmpSalary&quot;/&gt;        &lt;/resultMap&gt;    --&gt;    &lt;select id=&quot;getEmpByName&quot; resultType=&quot;com.luotao.domian.Employ&quot;&gt;        select        emp_id as &#x27;empId&#x27;,        emp_name as &#x27;empName&#x27;,        emp_salary as &#x27;empSalary&#x27;        from        $&#123;tableName&#125;        &lt;!--            #&#123;&#125; 做的是预编译处理（PreparedStatement），可以有效防止 SQL 注入。            #&#123;abc&#125; 表示从传入的参数中获取名为 abc 的值，并将其作为 PreparedStatement 的参数。        --&gt;        where        emp_name=#&#123;abc&#125;        &lt;!--            $&#123;&#125; 做的是字符串拼接，直接将变量值插入到 SQL 语句中。            $&#123;abc&#125; 会直接将 abc 的值替换到 SQL 语句中，不进行任何转义，存在 SQL 注入风险。            示例：where emp_name=&#x27;$&#123;abc&#125;&#x27;        --&gt;    &lt;/select&gt;    &lt;select id=&quot;getEmpSalaryById&quot; resultType=&quot;double&quot;&gt;        select emp_salary        from t_emp        where emp_id = #&#123;empId&#125;    &lt;/select&gt;    &lt;select id=&quot;getMinMaxAvgSalary&quot; resultType=&quot;map&quot;&gt;        select            emp_id,            min(emp_salary) as &#x27;minSalary&#x27;,            max(emp_salary) as &#x27;maxSalary&#x27;,            avg(emp_salary) as &#x27;avgSalary&#x27;        from t_emp    &lt;/select&gt;    &lt;!-- keyProperty 属性用于指定将数据库生成的主键值映射到实体类的哪个属性，key表示数据库的主键，property表示实体类的属性。--&gt;    &lt;insert id=&quot;addEmploy&quot; useGeneratedKeys=&quot;true&quot; keyProperty=&quot;empId&quot;&gt;        &lt;!--parameterType为实体类型，这些参数其实就是Employ的属性名,#&#123;通过getter方法获取Employ属性值与这些参数映射&#125;--&gt;        insert into t_emp(emp_id,emp_name,emp_salary) values (null,#&#123;empName&#125;,#&#123;empSalary&#125;)    &lt;/insert&gt;    &lt;insert id=&quot;addEmployByMap&quot;&gt;        &lt;!--parameterType为Map类型，这些参数其实就是map的key,#&#123;通过map.get(&quot;empName&quot;)获取value与这些参数映射&#125;--&gt;        insert into t_emp(emp_id,emp_name,emp_salary) values (null,#&#123;empName&#125;,#&#123;empSalary&#125;)    &lt;/insert&gt;&lt;/mapper&gt;
