import com.luotao.domian.Employ;import com.luotao.mapper.EmpMapper;import lombok.extern.slf4j.Slf4j;import org.apache.ibatis.io.Resources;import org.apache.ibatis.session.SqlSession;import org.apache.ibatis.session.SqlSessionFactory;import org.apache.ibatis.session.SqlSessionFactoryBuilder;import org.junit.jupiter.api.BeforeEach;import org.junit.jupiter.api.Test;import java.io.IOException;import java.io.InputStream;import java.util.HashMap;import java.util.Map;/** * @Classname EmpTest * @Description TODO * @Version 1.0.0 * @Date 2025/4/11 1:19 * @Author LuoTao */@Slf4jpublic class EmpTest &#123;    private EmpMapper empMapper;    private SqlSession sqlSession; //SqlSession 的事务默认是被暂存的，直到显示调用commit方法才会提交到数据库    @BeforeEach // @BeforeEach 注解用于标记一个方法，在每个测试方法执行之前都会调用该方法。这通常用于初始化测试环境或资源。    public void setup() throws IOException &#123;        // 步骤1：从类路径（src/main/resources）加载MyBatis全局配置文件        InputStream resourceAsStream = Resources.getResourceAsStream(&quot;mybatis-config.xml&quot;);        // 步骤2：根据配置文件构建数据库会话工厂        SqlSessionFactory sqlSessionFactory = new SqlSessionFactoryBuilder().build(resourceAsStream);        // 步骤3：获取一个数据库连接会话         sqlSession = sqlSessionFactory.openSession();        // 步骤4：获取Mapper代理对象(自动生成EmpMapper接口的实现类)：父接口指向一个实现了EmpMapper的类，实现的细节在`EmpMapper.xml`中(通过EmpMapper.xml中的SQL配置绑定接口方法)         empMapper = sqlSession.getMapper(EmpMapper.class);    &#125;    @Test    public void listTest()  &#123;        // 执行EmpMapper.xml中id=&quot;list&quot;的SQL语句,将查询结果自动映射为Employ对象列表//        empMapper.list(&quot;t&quot;,200D).forEach(System.out::println);        // 可以不用mapper,直接引用配置文件的命名空间下的id为list的SQL 查询。        // 第一个参数是 SQL 语句的完整路径，格式为 命名空间 + SQL 语句的 id，例如 com.luotao.mapper.EmpMapper.list。        //第二个参数是传递给 SQL 语句的参数，可以是一个 Map 或实体对象，        // 这里通过 HashMap 传递 empName 和 minEmpSalary 参数，key是String类型的sql占位符，value是Object类型可以自动转换empName的String或minEmpSalary的Double类型。        sqlSession.selectList(&quot;com.luotao.mapper.EmpMapper.list&quot;,new HashMap&lt;String,Object&gt;()&#123;&#123;            put(&quot;empName&quot;, &quot;t&quot;);           // 对应 SQL 中的 #&#123;empName&#125;            put(&quot;minEmpSalary&quot;, 200D);  // 对应 SQL 中的 #&#123;minEmpSalary&#125;        &#125;&#125;).forEach(System.out::println);    &#125;    @Test    public void listByResultMapTest()&#123;        empMapper.listByResultMap().forEach(System.out::println);    &#125;    @Test    public void getEmpByNameTest()  &#123;        // 执行EmpMapper.xml中id=&quot;getEmpByName&quot;的SQL语句,将查询结果自动映射为Employ对象        System.out.println(empMapper.getEmpByName(&quot;luotao&quot;,&quot;t_emp&quot;));    &#125;    @Test    public void getEmpSalaryById()  &#123;        System.out.println(String.format(&quot;该员工薪资为%s&quot;,  empMapper.getEmpSalaryById(Integer.valueOf(1))));    &#125;    @Test    public void getMinMaxAvgSalary()  &#123;         empMapper.getMinMaxAvgSalary().entrySet().forEach(kv -&gt;&#123;            System.out.println(String.format(&quot;%s=&gt;%s&quot;,kv.getKey(),kv.getValue() ));        &#125;);    &#125;    @Test    public void addEmployTest()  &#123;        Employ employ = new Employ();        employ.setEmpName(&quot;旺财&quot;);        employ.setEmpSalary(8000D);        try &#123;            // 执行EmpMapper.xml中id=&quot;addEmploy&quot;的SQL语句,将查询结果自动映射为Employ对象            System.out.println(empMapper.addEmploy(employ));            System.out.println(employ); // 如果配置了keyProperty=&quot;empId&quot;，则会将生成的主键映射到实体类的empId属性            sqlSession.commit();        &#125; catch (Exception e) &#123;            sqlSession.rollback();            System.out.println(e.getMessage());        &#125; finally &#123;            sqlSession.close();        &#125;    &#125;    @Test    public void addEmployByMap()  &#123;/*        Map map = Map.of(                &quot;empName&quot;,&quot;旺财&quot;,                &quot;empSalary&quot;,8000D);*/        // key必须和实体的属性名对应才能映射结果        Map&lt;String, Object&gt; map = new HashMap&lt;String, Object&gt;();        map.put(&quot;empName&quot;, &quot;旺财1&quot;);        map.put(&quot;empSalary&quot;, 8000D);        try &#123;            // 执行EmpMapper.xml中id=&quot;addEmployByMap&quot;的SQL语句,将查询结果自动映射为Map            System.out.println(empMapper.addEmployByMap(map));            sqlSession.commit();        &#125; catch (Exception e) &#123;            sqlSession.rollback();            System.out.println(e.getMessage());        &#125; finally &#123;            sqlSession.close();        &#125;    &#125;&#125;
