use `mybatis-example`;create table t_teacher(    tid   int auto_increment primary key,    tname varchar(20));create table t_stu(    sid       int auto_increment primary key,    sname     varchar(20),    teacherId int,    foreign key (teacherId) references t_teacher (tid));insert into t_teachervalues (0, &#x27;jim&#x27;),       (0, &#x27;tom&#x27;);insert into t_stuvalues (0, &#x27;jack&#x27;, 1),       (0, &#x27;john&#x27;, 1),       (0, &#x27;tony&#x27;, 2),       (0, &#x27;tomas&#x27;, 2),       (0, &#x27;tin&#x27;, 2);-- 每个教师的详细信息，教师表和教师资料表一对一CREATE TABLE t_teacher_profile (    profile_id INT AUTO_INCREMENT PRIMARY KEY, -- 主键    teacher_id INT UNIQUE,                     -- 外键，指向 t_teacher 表的 tid    profile_info VARCHAR(255),                 -- 教师的详细信息    FOREIGN KEY (teacher_id) REFERENCES t_teacher(tid));INSERT INTO t_teacher_profile (teacher_id, profile_info) VALUES (1, &#x27;Jim is a senior teacher with 10 years of experience.&#x27;),(2, &#x27;Tom specializes in mathematics and physics.&#x27;);
对一和对多关联
&lt;?xml version=&quot;1.0&quot; encoding=&quot;UTF-8&quot;?&gt;&lt;!-- MyBatis配置文件约束声明 --&gt;&lt;!DOCTYPE mapper        PUBLIC &quot;-//mybatis.org//DTD Mapper 3.0//EN&quot;        &quot;http://mybatis.org/dtd/mybatis-3-mapper.dtd&quot;&gt;&lt;!--在 mybatis-config.xml 中自动注册了 com.luotao.domian以及子包下类的别名,也开启了驼峰命名--&gt;&lt;!-- 映射器定义：将XML映射到EmpMapper接口，实现接口方法与SQL的绑定 --&gt;&lt;mapper namespace=&quot;com.luotao.mapper.TeacherMapper&quot;&gt;    &lt;select id=&quot;getTeacherList&quot; resultMap=&quot;teacherResultMap&quot;&gt;        select *        from t_teacher as tea                 left join             t_stu as stu on tea.tid = stu.teacherId                 left join             t_teacher_profile AS tprof ON tea.tid = tprof.teacher_id    &lt;/select&gt;    &lt;!--   mapUnderscoreToCamelCase已经满足不了需求，所以定义描述实体与查询结果的映射规则resultMap。--&gt;    &lt;resultMap id=&quot;teacherResultMap&quot; type=&quot;teacher&quot;&gt;        &lt;id column=&quot;tid&quot; property=&quot;tId&quot;/&gt;        &lt;result column=&quot;tname&quot; property=&quot;tName&quot;/&gt;        &lt;!-- 一对一关联：教师与教师资料            方式一：&lt;association&gt; 标签将查询结果中的某些列映射到一个 Java 类的属性上。            方式二：给列起别名         --&gt;        &lt;association property=&quot;teacherProfile&quot; javaType=&quot;teacherProfile&quot;&gt;            &lt;id column=&quot;profile_id&quot; property=&quot;profileId&quot;/&gt;            &lt;result column=&quot;teacher_id&quot; property=&quot;teacherId&quot;/&gt;            &lt;result column=&quot;profile_info&quot; property=&quot;profileInfo&quot;/&gt;        &lt;/association&gt;        &lt;!-- collection处理一对多关联：教师与学生            &lt;collection&gt; 标签：指定 Teacher 类中的一个集合属性，该属性用于存储与 Teacher 关联的多个 Student 对象。            ofType=&quot;student&quot;：指定集合中元素的类型。--&gt;        &lt;collection property=&quot;studentList&quot; ofType=&quot;student&quot;&gt;            &lt;id column=&quot;sid&quot; property=&quot;sId&quot;/&gt;            &lt;result column=&quot;sname&quot; property=&quot;sName&quot;/&gt;        &lt;/collection&gt;    &lt;/resultMap&gt;    &lt;!--一对一关联：教师与教师资料        方式二：除了使用 &lt;resultMap&gt; 和 &lt;association&gt; 标签来处理复杂对象映射外，还可以通过给列起别名，直接将查询结果中的列名映射到 Java 对象的属性上        数据库列名 as &#x27;Java对象.属性名&#x27;--&gt;    &lt;select id=&quot;getTeacherListByAs&quot; resultType=&quot;teacher&quot;&gt;        select tea.*,               tprof.profile_id as &#x27;teacherProfile.profileId&#x27;,               tprof.teacher_id as &#x27;teacherProfile.teacherId&#x27;,               tprof.profile_info as &#x27;teacherProfile.profileInfo&#x27;        from t_teacher as tea                 left join             t_teacher_profile AS tprof ON tea.tid = tprof.teacher_id    &lt;/select&gt;&lt;/mapper&gt;

详解Java异常处理机制
Java提供了一种结构化的方式来处理程序运行时可能出现的错误情况。
异常的基本概念
什么是异常
异常是程序运行过程中出现的非正常情况，如： - 程序逻辑错误 -
系统资源不足 - 用户操作错误 - 设备故障等
Java使用异常对象（Exception
Object）来表示这些异常情况，并提供了处理这些异常的机制。
异常的分类
Java中的异常主要分为三大类：

检查型异常（Checked Exception）

编译时异常，必须显式处理
继承自Exception类但不是RuntimeException的子类
例如：IOException, SQLException

非检查型异常（Unchecked Exception）

运行时异常，不强制处理
继承自RuntimeException
例如：NullPointerException, ArrayIndexOutOfBoundsException

错误（Error）

表示严重问题，通常无法恢复
继承自Error类
例如：OutOfMemoryError, StackOverflowError


Java异常类层次结构
Throwable (所有异常和错误的父类)├── Error (严重错误，通常无法恢复)│   ├── OutOfMemoryError│   ├── StackOverflowError│   └── ...└── Exception (异常情况，可以处理)    ├── IOException (检查型异常)    ├── SQLException (检查型异常)    ├── ClassNotFoundException (检查型异常)    ├── RuntimeException (非检查型异常)    │   ├── NullPointerException    │   ├── ArrayIndexOutOfBoundsException    │   ├── ArithmeticException    │   ├── IllegalArgumentException    │   └── ...    └── ...
异常处理语法
try-catch-finally
基本语法：
try &#123;    // 可能抛出异常的代码&#125; catch (ExceptionType1 e1) &#123;    // 处理ExceptionType1类型的异常&#125; catch (ExceptionType2 e2) &#123;    // 处理ExceptionType2类型的异常&#125; finally &#123;    // 无论是否发生异常，都会执行的代码    // 通常用于释放资源&#125;
示例：
public void readFile(String filename) &#123;    FileInputStream fis = null;    try &#123;        fis = new FileInputStream(filename);        int data;        while ((data = fis.read()) != -1) &#123;            System.out.print((char) data);        &#125;    &#125; catch (FileNotFoundException e) &#123;        System.err.println(&quot;文件不存在: &quot; + e.getMessage());    &#125; catch (IOException e) &#123;        System.err.println(&quot;读取文件错误: &quot; + e.getMessage());    &#125; finally &#123;        // 关闭资源        if (fis != null) &#123;            try &#123;                fis.close();            &#125; catch (IOException e) &#123;                System.err.println(&quot;关闭文件错误: &quot; + e.getMessage());            &#125;        &#125;    &#125;&#125;
try-with-resources (Java 7+)
自动资源管理，简化了资源的关闭操作：
public void readFile(String filename) &#123;    // 实现了AutoCloseable接口的资源会在try块结束后自动关闭    try (FileInputStream fis = new FileInputStream(filename)) &#123;        int data;        while ((data = fis.read()) != -1) &#123;            System.out.print((char) data);        &#125;    &#125; catch (FileNotFoundException e) &#123;        System.err.println(&quot;文件不存在: &quot; + e.getMessage());    &#125; catch (IOException e) &#123;        System.err.println(&quot;读取文件错误: &quot; + e.getMessage());    &#125;    // 不需要finally块来关闭资源&#125;
多个资源的情况：
try (FileInputStream fis = new FileInputStream(&quot;input.txt&quot;);     FileOutputStream fos = new FileOutputStream(&quot;output.txt&quot;)) &#123;    // 使用fis和fos&#125; catch (IOException e) &#123;    // 处理异常&#125;
多重捕获 (Java 7+)
一个catch块可以处理多种类型的异常：
try &#123;    // 可能抛出异常的代码&#125; catch (FileNotFoundException | SQLException e) &#123;    // 处理FileNotFoundException或SQLException    System.err.println(&quot;发生异常: &quot; + e.getMessage());&#125;
throws关键字
用于声明方法可能抛出的检查型异常：
public void readFile(String filename) throws IOException &#123;    FileInputStream fis = new FileInputStream(filename); // 可能抛出FileNotFoundException    int data;    while ((data = fis.read()) != -1) &#123; // 可能抛出IOException        System.out.print((char) data);    &#125;    fis.close(); // 可能抛出IOException&#125;
调用带throws声明的方法：
public void processFile(String filename) &#123;    try &#123;        readFile(filename);    &#125; catch (IOException e) &#123;        System.err.println(&quot;处理文件错误: &quot; + e.getMessage());    &#125;&#125;
throw关键字
用于手动抛出异常：
public void validateAge(int age) &#123;    if (age &lt; 0) &#123;        throw new IllegalArgumentException(&quot;年龄不能为负数&quot;);    &#125;    if (age &gt; 150) &#123;        throw new IllegalArgumentException(&quot;年龄不合理&quot;);    &#125;    System.out.println(&quot;年龄验证通过: &quot; + age);&#125;
自定义异常
当标准异常不能满足需求时，可以创建自定义异常：
// 自定义检查型异常public class InsufficientFundsException extends Exception &#123;    private double amount;        public InsufficientFundsException(double amount) &#123;        super(&quot;余额不足，还差: &quot; + amount);        this.amount = amount;    &#125;        public double getAmount() &#123;        return amount;    &#125;&#125;// 自定义运行时异常public class InvalidUserException extends RuntimeException &#123;    public InvalidUserException(String message) &#123;        super(message);    &#125;&#125;
使用自定义异常：
public class BankAccount &#123;    private double balance;        public void withdraw(double amount) throws InsufficientFundsException &#123;        if (amount &gt; balance) &#123;            throw new InsufficientFundsException(amount - balance);        &#125;        balance -= amount;    &#125;        public void validateUser(String username) &#123;        if (username == null || username.trim().isEmpty()) &#123;            throw new InvalidUserException(&quot;用户名不能为空&quot;);        &#125;    &#125;&#125;
异常链
异常链允许将一个异常包装在另一个异常中，保留原始异常信息：
try &#123;    // 数据库操作&#125; catch (SQLException e) &#123;    // 包装原始异常，转换为应用层异常    throw new ServiceException(&quot;数据库操作失败&quot;, e);&#125;
常见异常及其处理方法
NullPointerException
// 避免NullPointerExceptionpublic void processString(String str) &#123;    // 不好的方式    int length = str.length(); // 如果str为null，抛出NullPointerException        // 好的方式    if (str != null) &#123;        int length = str.length();    &#125;        // 更好的方式 (Java 8+)    Optional&lt;String&gt; optStr = Optional.ofNullable(str);    optStr.ifPresent(s -&gt; &#123;        int length = s.length();    &#125;);&#125;
ArrayIndexOutOfBoundsException
// 避免ArrayIndexOutOfBoundsExceptionpublic void accessArray(int[] array, int index) &#123;    // 不好的方式    int value = array[index]; // 如果index超出范围，抛出异常        // 好的方式    if (array != null &amp;&amp; index &gt;= 0 &amp;&amp; index &lt; array.length) &#123;        int value = array[index];    &#125;&#125;
NumberFormatException
// 避免NumberFormatExceptionpublic int parseInteger(String str) &#123;    // 不好的方式    return Integer.parseInt(str); // 如果str不是有效的数字，抛出异常        // 好的方式    try &#123;        return Integer.parseInt(str);    &#125; catch (NumberFormatException e) &#123;        System.err.println(&quot;无效的数字格式: &quot; + str);        return 0; // 或其他默认值    &#125;&#125;
异常处理的最佳实践

只捕获能够处理的异常 // 不好的方式try &#123;    // 代码&#125; catch (Exception e) &#123;    e.printStackTrace(); // 捕获所有异常但没有适当处理&#125;// 好的方式try &#123;    // 代码&#125; catch (IOException e) &#123;    // 针对IO异常的具体处理&#125; catch (SQLException e) &#123;    // 针对SQL异常的具体处理&#125;
不要忽略异常 // 不好的方式try &#123;    // 代码&#125; catch (Exception e) &#123;    // 空的catch块，完全忽略异常&#125;// 好的方式try &#123;    // 代码&#125; catch (Exception e) &#123;    logger.error(&quot;发生错误&quot;, e);    // 适当的错误处理&#125;
释放资源的正确方式 // Java 7之前FileInputStream fis = null;try &#123;    fis = new FileInputStream(&quot;file.txt&quot;);    // 使用fis&#125; catch (IOException e) &#123;    // 处理异常&#125; finally &#123;    if (fis != null) &#123;        try &#123;            fis.close();        &#125; catch (IOException e) &#123;            // 处理关闭异常        &#125;    &#125;&#125;// Java 7及以后try (FileInputStream fis = new FileInputStream(&quot;file.txt&quot;)) &#123;    // 使用fis&#125; catch (IOException e) &#123;    // 处理异常&#125;
异常的粒度 // 粒度太粗try &#123;    // 很多操作&#125; catch (Exception e) &#123;    // 处理异常&#125;// 适当的粒度try &#123;    // 操作1&#125; catch (SpecificException e) &#123;    // 处理特定异常&#125;try &#123;    // 操作2&#125; catch (AnotherException e) &#123;    // 处理另一种异常&#125;
使用标准异常 // 不好的方式throw new Exception(&quot;参数无效&quot;);// 好的方式throw new IllegalArgumentException(&quot;参数无效&quot;);
记录异常信息 try &#123;    // 代码&#125; catch (Exception e) &#123;    logger.error(&quot;操作失败: &quot; + e.getMessage(), e);    // 包含异常堆栈信息&#125;
异常转换 try &#123;    // 底层操作&#125; catch (LowLevelException e) &#123;    // 转换为更有意义的高级异常    throw new BusinessException(&quot;业务操作失败&quot;, e);&#125;
